<?php require_once dirname(__DIR__).'/lib.php';session_start();if(empty($_SESSION['admin']))json_out(['ok'=>false,'message'=>'관리자 로그인이 필요합니다.'],403);try{$id=(int)($_POST['id']??0);if(!isset($_FILES['pdf'])||$_FILES['pdf']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('PDF 업로드 실패');if($_FILES['pdf']['size']>12000000)throw new RuntimeException('PDF가 너무 큽니다.');$head=file_get_contents($_FILES['pdf']['tmp_name'],false,null,0,4);if($head!=='%PDF')throw new RuntimeException('PDF 파일이 아닙니다.');$dir=dirname(__DIR__).'/storage/pdfs';$name='lease_'.$id.'_'.date('YmdHis').'_'.token(4).'.pdf';move_uploaded_file($_FILES['pdf']['tmp_name'],$dir.'/'.$name);$web='storage/pdfs/'.$name;$s=db()->prepare("UPDATE contracts SET final_pdf=?,updated_at=NOW() WHERE id=? AND status='completed'");$s->execute([$web,$id]);audit($id,'admin','pdf_generated',['file'=>$name]);json_out(['ok'=>true,'message'=>'최종 PDF가 저장되었습니다.','url'=>cfg('base_url').'/download.php?id='.$id]);}catch(Throwable $e){json_out(['ok'=>false,'message'=>$e->getMessage()],400);}